// analysis diagnostic DFS: collect depth frontier statistics without exhaustive completion.
//
// It follows the repaired cap<=5 Wang saturation semantics and can include the
// same cover one-row residual-capacity tests and mixed cuts.  When a search node
// reaches --stop-depth, it records aggregate properties of the current selected
// support P and future domain F: |F|, need=19-|P|, and the best margin over cover
// rows, margin = (cap-|P cap R|)+|F\R|-need.  Negative margin would be a sound
// one-row branch certificate.  This is a measurement tool, not a proof unless
// the run is complete and zero solutions are reported.

#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

static constexpr int MAXP=255, WORDS=4;
static bool bit4(const uint64_t w[WORDS],int p){return (w[p>>6]>>(p&63))&1ULL;}
static void setbit4(uint64_t w[WORDS],int p){w[p>>6]|=1ULL<<(p&63);} static void clrbit4(uint64_t w[WORDS],int p){w[p>>6]&=~(1ULL<<(p&63));}
static int pop4(const uint64_t w[WORDS]){return __builtin_popcountll(w[0])+__builtin_popcountll(w[1])+__builtin_popcountll(w[2])+__builtin_popcountll(w[3]);}
struct Row{uint8_t cap=0,dim=0;uint16_t reserved=0;uint64_t word[WORDS]={0,0,0,0};};
struct Cut{uint8_t K=0;uint64_t w1[WORDS]={0,0,0,0};uint64_t w2[WORDS]={0,0,0,0};uint8_t coeff[256]{};};
struct Branch{int id=-1,rep=0;uint64_t forbid[WORDS]={0,0,0,0};};
struct Frontier{uint64_t nodes=0; long long best_margin_min=9999,best_margin_max=-9999; std::array<uint64_t,64> margin_hist{}; std::array<uint64_t,256> avail_hist{}; std::array<uint64_t,20> best_cap_hist{}; std::vector<std::string> examples;};
struct Result{int branch=-1,rep=0,target=0,stop_depth=0,max_depth=0;double elapsed_sec=0;bool timeout=false,complete=false,forced_infeasible=false;uint64_t calls=0,candidate_tests=0,overcap=0,cover_overcap=0,global_shortage=0,mixed_prunes=0,cover_prunes=0,mixed_checks=0,cover_checks=0,cover_row_tests=0,saturated=0,sat_removed=0,frontier_hits=0,solutions=0;std::array<uint64_t,32> nodes{};std::array<uint64_t,32> mixed_depth{};std::array<uint64_t,32> cover_depth{};Frontier frontier;};
static std::string arr32(const std::array<uint64_t,32>&a,int upto){std::ostringstream o;o<<"[";for(int i=0;i<=upto&&i<32;i++){if(i)o<<",";o<<a[i];}o<<"]";return o.str();}
static std::string arr64_nonzero(const std::array<uint64_t,64>&a,int offset){std::ostringstream o;o<<"{";bool first=true;for(int i=0;i<64;i++)if(a[i]){if(!first)o<<",";first=false;o<<"\""<<(i-offset)<<"\":"<<a[i];}o<<"}";return o.str();}
static std::string arr256_nonzero(const std::array<uint64_t,256>&a){std::ostringstream o;o<<"{";bool first=true;for(int i=0;i<256;i++)if(a[i]){if(!first)o<<",";first=false;o<<"\""<<i<<"\":"<<a[i];}o<<"}";return o.str();}
static std::string arr20_nonzero(const std::array<uint64_t,20>&a){std::ostringstream o;o<<"{";bool first=true;for(int i=0;i<20;i++)if(a[i]){if(!first)o<<",";first=false;o<<"\""<<i<<"\":"<<a[i];}o<<"}";return o.str();}
static bool load_rows(const std::string&path,std::vector<Row>&rows){if(path.empty())return true;std::ifstream in(path,std::ios::binary);if(!in){std::cerr<<"cannot open "<<path<<"\n";return false;}char magic[8];in.read(magic,8);if(!in||std::memcmp(magic,"E11WANG1",8)!=0){std::cerr<<"bad row magic\n";return false;}uint32_t n;in.read((char*)&n,4);rows.resize(n);for(uint32_t i=0;i<n;i++){in.read((char*)&rows[i].cap,1);in.read((char*)&rows[i].dim,1);in.read((char*)&rows[i].reserved,2);for(int w=0;w<WORDS;w++)in.read((char*)&rows[i].word[w],8);}return bool(in);} 
static bool load_cuts(const std::string&path,std::vector<Cut>&cuts){if(path.empty())return true;std::ifstream in(path,std::ios::binary);if(!in){std::cerr<<"cannot open cuts\n";return false;}char magic[8];in.read(magic,8);if(!in||std::memcmp(magic,"MIXCUT1\0",8)!=0){std::cerr<<"bad cut magic\n";return false;}uint32_t n;in.read((char*)&n,4);cuts.resize(n);for(uint32_t i=0;i<n;i++){uint8_t flags;uint16_t res;in.read((char*)&cuts[i].K,1);in.read((char*)&flags,1);in.read((char*)&res,2);for(int w=0;w<WORDS;w++)in.read((char*)&cuts[i].w1[w],8);for(int w=0;w<WORDS;w++)in.read((char*)&cuts[i].w2[w],8);for(int p=1;p<=MAXP;p++)cuts[i].coeff[p]=bit4(cuts[i].w2,p)?2:(bit4(cuts[i].w1,p)?1:0);}return bool(in);} 
static std::vector<std::vector<uint32_t>> point_rows(const std::vector<Row>&rows){std::vector<std::vector<uint32_t>>pr(256);for(uint32_t i=0;i<rows.size();i++)for(int p=1;p<=MAXP;p++)if(bit4(rows[i].word,p))pr[p].push_back(i);return pr;}
static std::vector<Branch> branches(){const int reps[8]={1,4,5,8,10,40,42,80};const std::vector<std::vector<int>> members={{1,2,3},{4,32,36},{5,6,7,33,34,35,37,38,39},{8,9,12,13,16,18,20,22,24,27,28,31,64,65,72,73,96,97,108,109,128,130,144,146,160,162,180,182,192,195,216,219,224,227,252,255},{10,11,14,15,17,19,21,23,25,26,29,30,66,67,74,75,98,99,110,111,129,131,145,147,161,163,181,183,193,194,217,218,225,226,253,254},{40,41,44,45,48,50,52,54,56,59,60,63,68,69,76,77,100,101,104,105,132,134,148,150,164,166,176,178,196,199,220,223,228,231,248,251},{42,43,46,47,49,51,53,55,57,58,61,62,70,71,78,79,102,103,106,107,133,135,149,151,165,167,177,179,197,198,221,222,229,230,249,250},{80,81,82,83,84,85,86,87,88,89,90,91,92,93,94,95,112,113,114,115,116,117,118,119,120,121,122,123,124,125,126,127,136,137,138,139,140,141,142,143,152,153,154,155,156,157,158,159,168,169,170,171,172,173,174,175,184,185,186,187,188,189,190,191,200,201,202,203,204,205,206,207,208,209,210,211,212,213,214,215,232,233,234,235,236,237,238,239,240,241,242,243,244,245,246,247}};std::vector<Branch>out;uint64_t forbid[WORDS]={0,0,0,0};for(int i=0;i<8;i++){Branch b;b.id=i;b.rep=reps[i];for(int w=0;w<WORDS;w++)b.forbid[w]=forbid[w];out.push_back(b);for(int p:members[i])setbit4(forbid,p);}return out;}
static std::vector<int> parse_list(const std::string&s){std::vector<int>v;size_t pos=0;while(pos<s.size()){size_t nx=s.find(',',pos);if(nx==std::string::npos)nx=s.size();if(nx>pos){int p=std::stoi(s.substr(pos,nx-pos));if(1<=p&&p<=MAXP)v.push_back(p);}pos=nx+1;}std::sort(v.begin(),v.end());v.erase(std::unique(v.begin(),v.end()),v.end());return v;}
struct Searcher{const std::vector<Row>&rows;const std::vector<std::vector<uint32_t>>&pr;const std::vector<Row>&cov;const std::vector<std::vector<uint32_t>>&cpr;const std::vector<Cut>&cuts;int target,stop_depth,cover_min_depth,cover_max_slack;double limit;bool use_mixed;std::chrono::steady_clock::time_point start;std::vector<uint8_t>cnt,ccnt;std::vector<int16_t>lhs;uint64_t dom[WORDS];std::vector<int>chosen;Result res;Searcher(const std::vector<Row>&r,const std::vector<std::vector<uint32_t>>&p,const std::vector<Row>&cr,const std::vector<std::vector<uint32_t>>&cp,const std::vector<Cut>&c,int t,int sd,double lim,int cmd,int cms):rows(r),pr(p),cov(cr),cpr(cp),cuts(c),target(t),stop_depth(sd),cover_min_depth(cmd),cover_max_slack(cms),limit(lim),use_mixed(!c.empty()),cnt(r.size(),0),ccnt(cr.size(),0),lhs(c.size(),0){}
 bool timed()const{return limit>0&&std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()>=limit;} void full_domain(){dom[0]=dom[1]=dom[2]=dom[3]=~0ULL;dom[0]&=~1ULL;} bool in_dom(int p)const{return bit4(dom,p);} int avail_from(int minp)const{int c=0;for(int p=minp;p<=MAXP;p++)if(in_dom(p))c++;return c;} void future_words(int minp,uint64_t out[WORDS])const{for(int w=0;w<WORDS;w++)out[w]=dom[w];if(minp>1)for(int p=1;p<minp&&p<=MAXP;p++)clrbit4(out,p);} 
 bool mixed_possible(int minp,int need){if(!use_mixed)return true;res.mixed_checks+=cuts.size();uint64_t fut[WORDS];future_words(minp,fut);for(size_t i=0;i<cuts.size();i++){uint64_t a1[WORDS],a2[WORDS];for(int w=0;w<WORDS;w++){a1[w]=fut[w]&cuts[i].w1[w];a2[w]=fut[w]&cuts[i].w2[w];}int c2=pop4(a2),c1=pop4(a1);int take2=std::min(c2,need);int take1=std::min(c1,need-take2);if(lhs[i]+2*take2+take1<cuts[i].K){res.mixed_prunes++;int d=chosen.size();if(d<32)res.mixed_depth[d]++;return false;}}return true;}
 bool cover_possible(int minp,int need){if(cov.empty())return true;uint64_t fut[WORDS];future_words(minp,fut);int avail=pop4(fut);int depth=chosen.size();int slack=avail-need;bool thr=(need==0)||(depth>=cover_min_depth)||(cover_max_slack>=0&&slack<=cover_max_slack);if(!thr)return true;res.cover_checks++;for(size_t i=0;i<cov.size();i++){int u=(int)cov[i].cap-(int)ccnt[i];if(u>=need)continue;res.cover_row_tests++;if(u<0){res.cover_prunes++;if(depth<32)res.cover_depth[depth]++;return false;}uint64_t a[WORDS];for(int w=0;w<WORDS;w++)a[w]=fut[w]&cov[i].word[w];int in=pop4(a),outside=avail-in;if(u+outside<need){res.cover_prunes++;if(depth<32)res.cover_depth[depth]++;return false;}}return true;}
 void record_frontier(int minp){res.frontier_hits++;res.frontier.nodes++;uint64_t fut[WORDS];future_words(minp,fut);int avail=pop4(fut);int need=target-(int)chosen.size();if(avail>=0&&avail<256)res.frontier.avail_hist[avail]++;long long best=9999;int bestcap=-1,bestidx=-1,bestu=0,bestin=0,bestout=0;for(size_t i=0;i<cov.size();i++){int u=(int)cov[i].cap-(int)ccnt[i];uint64_t a[WORDS];for(int w=0;w<WORDS;w++)a[w]=fut[w]&cov[i].word[w];int in=pop4(a),out=avail-in;long long margin=(long long)u+out-need;if(margin<best){best=margin;bestcap=cov[i].cap;bestidx=(int)i;bestu=u;bestin=in;bestout=out;}}res.frontier.best_margin_min=std::min(res.frontier.best_margin_min,best);res.frontier.best_margin_max=std::max(res.frontier.best_margin_max,best);int bi=(int)std::max<long long>(-31,std::min<long long>(32,best))+31;res.frontier.margin_hist[bi]++;if(0<=bestcap&&bestcap<20)res.frontier.best_cap_hist[bestcap]++;if(res.frontier.examples.size()<10){std::ostringstream o;o<<"{\"chosen\":[";for(size_t j=0;j<chosen.size();j++){if(j)o<<",";o<<chosen[j];}o<<"],\"minp\":"<<minp<<",\"need\":"<<need<<",\"avail\":"<<avail<<",\"best_margin\":"<<best<<",\"best_row\":"<<bestidx<<",\"best_cap\":"<<bestcap<<",\"best_u\":"<<bestu<<",\"best_in\":"<<bestin<<",\"best_out\":"<<bestout<<"}";res.frontier.examples.push_back(o.str());}}
 bool try_select(int q,std::vector<uint32_t>&t,std::vector<uint32_t>&ct,uint64_t old[WORDS]){res.candidate_tests++;for(int w=0;w<WORDS;w++)old[w]=dom[w];if(!in_dom(q))return false;for(uint32_t ri:pr[q])if((int)cnt[ri]+1>rows[ri].cap){res.overcap++;return false;}for(uint32_t ri:cpr[q])if((int)ccnt[ri]+1>cov[ri].cap){res.cover_overcap++;return false;}clrbit4(dom,q);for(uint32_t ri:pr[q]){cnt[ri]++;t.push_back(ri);}for(uint32_t ri:cpr[q]){ccnt[ri]++;ct.push_back(ri);}for(size_t i=0;i<cuts.size();i++)lhs[i]+=cuts[i].coeff[q];for(uint32_t ri:t)if(cnt[ri]==rows[ri].cap){res.saturated++;int before=pop4(dom);for(int w=0;w<WORDS;w++)dom[w]&=~rows[ri].word[w];int after=pop4(dom);if(before>after)res.sat_removed+=before-after;}return true;}
 void undo_select(int q,const std::vector<uint32_t>&t,const std::vector<uint32_t>&ct,const uint64_t old[WORDS]){for(size_t i=0;i<cuts.size();i++)lhs[i]-=cuts[i].coeff[q];for(auto it=t.rbegin();it!=t.rend();++it)cnt[*it]--;for(auto it=ct.rbegin();it!=ct.rend();++it)ccnt[*it]--;for(int w=0;w<WORDS;w++)dom[w]=old[w];}
 bool force_points(const std::vector<int>&force){for(int p:force){if(!in_dom(p)){res.forced_infeasible=true;return false;}std::vector<uint32_t>t,ct;uint64_t old[WORDS];if(!try_select(p,t,ct,old)){res.forced_infeasible=true;return false;}chosen.push_back(p);}return true;}
 void dfs(int minp){if(res.timeout)return;if((res.calls++&0x3FFFULL)==0&&timed()){res.timeout=true;return;}int d=chosen.size();if(d>res.max_depth)res.max_depth=d;if(d==stop_depth){record_frontier(minp);return;}if(d==target){if(!cover_possible(MAXP+1,0))return;if(!mixed_possible(MAXP+1,0))return;res.solutions++;return;}int need=target-d;int avail=avail_from(minp);if(avail<need){res.global_shortage++;return;}if(!cover_possible(minp,need))return;if(!mixed_possible(minp,need))return;for(int q=minp;q<=MAXP;q++){if(MAXP-q+1<need)break;if(!in_dom(q))continue;if(avail_from(q)<need)break;std::vector<uint32_t>t,ct;uint64_t old[WORDS];if(try_select(q,t,ct,old)){chosen.push_back(q);int nd=chosen.size();if(nd<32)res.nodes[nd]++;dfs(q+1);chosen.pop_back();undo_select(q,t,ct,old);}if(res.timeout)return;}}
 Result run(const uint64_t forbidden[WORDS],const std::vector<int>&force,int min_after,int branch,int rep){res=Result();res.branch=branch;res.rep=rep;res.target=target;res.stop_depth=stop_depth;res.nodes.fill(0);res.mixed_depth.fill(0);res.cover_depth.fill(0);res.frontier.margin_hist.fill(0);res.frontier.avail_hist.fill(0);res.frontier.best_cap_hist.fill(0);res.nodes[0]=1;std::fill(cnt.begin(),cnt.end(),0);std::fill(ccnt.begin(),ccnt.end(),0);std::fill(lhs.begin(),lhs.end(),0);chosen.clear();full_domain();for(int w=0;w<WORDS;w++)dom[w]&=~forbidden[w];for(const auto&r:rows)if(r.cap==0){int before=pop4(dom);for(int w=0;w<WORDS;w++)dom[w]&=~r.word[w];res.sat_removed+=std::max(0,before-pop4(dom));}start=std::chrono::steady_clock::now();if(force_points(force)){int d=chosen.size();if(d<32)res.nodes[d]=std::max<uint64_t>(res.nodes[d],1);dfs(min_after);}res.elapsed_sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();res.complete=!res.timeout;return res;}};
static std::string frontier_json(const Frontier&f){std::ostringstream o;o<<"{\"nodes\":"<<f.nodes<<",\"best_margin_min\":"<<f.best_margin_min<<",\"best_margin_max\":"<<f.best_margin_max<<",\"best_margin_hist\":"<<arr64_nonzero(f.margin_hist,31)<<",\"avail_hist\":"<<arr256_nonzero(f.avail_hist)<<",\"best_cap_hist\":"<<arr20_nonzero(f.best_cap_hist)<<",\"examples\":[";for(size_t i=0;i<f.examples.size();i++){if(i)o<<",";o<<f.examples[i];}o<<"]}";return o.str();}
static std::string rjson(const Result&r){std::ostringstream o;o<<"{\"branch\":"<<r.branch<<",\"rep\":"<<r.rep<<",\"target\":"<<r.target<<",\"stop_depth\":"<<r.stop_depth<<",\"elapsed_sec\":"<<std::fixed<<std::setprecision(6)<<r.elapsed_sec<<",\"timeout\":"<<(r.timeout?"true":"false")<<",\"complete\":"<<(r.complete?"true":"false")<<",\"forced_infeasible\":"<<(r.forced_infeasible?"true":"false")<<",\"recursive_calls\":"<<r.calls<<",\"candidate_tests\":"<<r.candidate_tests<<",\"overcap_rejects\":"<<r.overcap<<",\"cover_overcap_rejects\":"<<r.cover_overcap<<",\"global_shortage\":"<<r.global_shortage<<",\"mixed_prunes\":"<<r.mixed_prunes<<",\"cover_prunes\":"<<r.cover_prunes<<",\"mixed_checks\":"<<r.mixed_checks<<",\"cover_checks\":"<<r.cover_checks<<",\"cover_row_tests\":"<<r.cover_row_tests<<",\"saturated_rows\":"<<r.saturated<<",\"saturation_removed_points\":"<<r.sat_removed<<",\"solutions\":"<<r.solutions<<",\"max_depth\":"<<r.max_depth<<",\"node_count_by_depth\":"<<arr32(r.nodes,std::min(31,r.target))<<",\"mixed_prune_depth\":"<<arr32(r.mixed_depth,std::min(31,r.target))<<",\"cover_prune_depth\":"<<arr32(r.cover_depth,std::min(31,r.target))<<",\"frontier\":"<<frontier_json(r.frontier)<<"}";return o.str();}
int main(int argc,char**argv){std::string cons,covers,cuts,outp,force_s,exclude_s;int target=19,branch=-2,stop_depth=12,cover_min_depth=999,cover_max_slack=-1;double lim=60;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--constraints"&&i+1<argc)cons=argv[++i];else if(a=="--cover-constraints"&&i+1<argc)covers=argv[++i];else if(a=="--cuts"&&i+1<argc)cuts=argv[++i];else if(a=="--output"&&i+1<argc)outp=argv[++i];else if(a=="--target"&&i+1<argc)target=std::stoi(argv[++i]);else if(a=="--branch"&&i+1<argc)branch=std::stoi(argv[++i]);else if(a=="--timeout"&&i+1<argc)lim=std::stod(argv[++i]);else if(a=="--stop-depth"&&i+1<argc)stop_depth=std::stoi(argv[++i]);else if(a=="--cover-min-depth"&&i+1<argc)cover_min_depth=std::stoi(argv[++i]);else if(a=="--cover-max-slack"&&i+1<argc)cover_max_slack=std::stoi(argv[++i]);else if(a=="--force"&&i+1<argc)force_s=argv[++i];else if(a=="--exclude"&&i+1<argc)exclude_s=argv[++i];else{std::cerr<<"bad arg "<<a<<"\n";return 2;}}if(cons.empty()||branch<0){std::cerr<<"usage --constraints FILE --cover-constraints FILE --branch B --stop-depth D ...\n";return 2;}std::vector<Row>rows,cov; if(!load_rows(cons,rows))return 1; if(!load_rows(covers,cov))return 1; std::vector<Cut>cutv; if(!load_cuts(cuts,cutv))return 1; auto pr=point_rows(rows), cpr=point_rows(cov); auto bs=branches(); Branch br=bs[branch]; std::vector<int>force=parse_list(force_s),exclude=parse_list(exclude_s); uint64_t forb[WORDS]; for(int w=0;w<WORDS;w++)forb[w]=br.forbid[w]; for(int p:exclude)setbit4(forb,p); force.push_back(br.rep); std::sort(force.begin(),force.end()); force.erase(std::unique(force.begin(),force.end()),force.end()); Searcher S(rows,pr,cov,cpr,cutv,target,stop_depth,lim,cover_min_depth,cover_max_slack); Result r=S.run(forb,force,br.rep+1,br.id,br.rep); std::string js=rjson(r); std::cout<<js<<"\n"; if(!outp.empty()){std::ofstream f(outp);f<<"{\n  \"schema\": \"s0908_cover_frontier_stats_v1\",\n  \"constraints_path\": \""<<cons<<"\",\n  \"cover_constraints_path\": \""<<covers<<"\",\n  \"cut_path\": \""<<cuts<<"\",\n  \"constraint_count\": "<<rows.size()<<",\n  \"cover_constraint_count\": "<<cov.size()<<",\n  \"mixed_cut_count\": "<<cutv.size()<<",\n  \"result\": "<<js<<"\n}\n"; std::cerr<<"wrote "<<outp<<"\n";}return 0;}
